    await page.goto('/sample-app', { waitUntil: 'domcontentloaded' });

    // [Step 2: id=step-402] Wait for Settlement Batch Webhook Response
    await page.waitForResponse((res) => res.url().includes('/api/platform') && res.status() === 200);

    // [Step 3: id=step-403] Verify Settlement Batch Reconciled Status
    await expect(page.getByTestId('order-status-badge')).toHaveText('Batch Settlement Completed #99');

  });
});
